int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *ohead = &sbi->s_orphan;
    struct ext4_orphan *op;
    int ret = 0;

    if (!ext4_has_feature_orphan(inode->i_sb))
        return 0;

    mutex_lock(&ohead->orphan_lock);

    list_for_each_entry(op, &ohead->orphan_list, list) {
        if (op->ino == inode->i_ino) {
            list_del(&op->list);
            kmem_cache_free(op);
            break;
        }
    }

    if (handle) {
        ret = ext4_mark_super_dirty(handle, inode->i_sb);
        if (ret < 0) {
            mutex_unlock(&ohead->orphan_lock);
            return ret;
        }
    }

    mutex_unlock(&ohead->orphan_lock);
    return 0;
}
